import './neon-progress-circle.scss';
import { NeonWidget } from '../shared/neon-widget';
import { dynamicText, createElement, updateDynamicText, updateConditionalElements, createElementIf, dynamicAttr, updateDynamicAttributeOnChildren, } from '../shared/dom-manipulation';
export class NeonProgressCircle extends NeonWidget {
    constructor() {
        super(...arguments);
        this.widgetTag = 'neon-progress-circle';
        this.value = 0;
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'data-size',
            'data-high-contrast',
            'data-value',
            'data-max-value',
            'data-percentage',
            'data-text',
            'data-state'
        ];
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'data-size':
                this.updateVisualization();
                updateDynamicAttributeOnChildren(this, 'class');
                updateDynamicAttributeOnChildren(this, 'data-size');
                break;
            case 'data-high-contrast':
                updateDynamicAttributeOnChildren(this, 'class');
                break;
            case 'data-value':
            case 'data-max-value':
            case 'data-percentage':
                if (this.requestAnimationFrameId) {
                    cancelAnimationFrame(this.requestAnimationFrameId);
                }
                this.updatePercentage();
                break;
            case 'data-text':
                updateDynamicText(this);
                break;
            case 'data-state':
                this.updateVisualization();
                updateConditionalElements(this);
                updateDynamicAttributeOnChildren(this, 'data-icon');
                break;
            default:
        }
    }
    // Calculate the percentage, defaulting to data-percentage, and then using data-value and data-max-value as a fallback
    // returns a number between 0 and 100
    getNumberForValueString() {
        if (this.getAttribute('data-percentage') != null) {
            const number = this.getAttribute('data-percentage');
            if (number != null) {
                return Number((parseFloat(number) * 100).toFixed(0));
            }
        }
        const value = parseFloat(this.getAttribute('data-value') || '0');
        const max = parseFloat(this.getAttribute('data-max-value') || '100');
        if (value >= 0 && max > 0) {
            return Number(((value / max) * 100).toFixed(0));
        }
        return 0;
    }
    getClasses() {
        const classes = ['neon-progress-circle'];
        if (this.getAttribute('data-high-contrast') === 'true') {
            classes.push('neon-progress-circle-high-contrast');
        }
        return classes.join(' ');
    }
    getStateIcon() {
        switch (this.getAttribute('data-state')) {
            case 'success':
                return 'status-check';
            case 'error':
                return 'status-error';
            default:
                return undefined;
        }
    }
    // the icon component sizes do not directly correlate to the progress circle sizes
    getStateIconSize() {
        switch (this.getAttribute('data-size')) {
            case 'small':
                return 'x-small';
            case 'medium':
                return 'medium';
            case 'large':
                return 'xxx-large';
            case 'x-large':
                return '5x-large';
            default:
                return 'medium';
        }
    }
    // To get the circumference of the circle we use the formula 2 * PI * r
    // where r is the radius of the circle
    // here the radius = width - stroke-width  / 2
    // because the stroke is on the outside of the circle
    getStrokeDasharray() {
        switch (this.getAttribute('data-size')) {
            case 'small':
                return Math.PI * 2 * 7;
            case 'large':
                return Math.PI * 2 * 28;
            case 'x-large':
                return Math.PI * 2 * 42;
            default:
                return Math.PI * 2 * 14;
        }
    }
    // the dashoffset is the amount of the dasharray that is not filled
    // the dasharray is the circumference of the circle
    // so if the dashoffset is equal to the dasharray, the circle is empty.
    // If the dashoffset is 0, the circle is full.
    // If you consider this unintuitive it is because it is.
    // address all complaints to the svg standards committee.
    getStrokeDashoffset() {
        switch (this.getAttribute('data-state')) {
            case 'success':
            case 'error':
                return 0;
            case 'undetermined':
                return this.getStrokeDasharray() * 0.75;
        }
        if (this.getNumberForValueString() === 0) {
            return this.getStrokeDasharray();
        }
        return this.getStrokeDasharray() - Math.min(this.getStrokeDasharray(), (this.getStrokeDasharray() * this.getNumberForValueString() / 100));
    }
    updateVisualization() {
        requestAnimationFrame(() => {
            if (!this.dataVisualizationForeground || !this.dataVisualizationBackground) {
                return;
            }
            this.dataVisualizationBackground.style.strokeDasharray = this.getStrokeDasharray().toString() + 'px';
            this.dataVisualizationForeground.style.strokeDasharray = this.getStrokeDasharray().toString() + 'px';
            this.dataVisualizationForeground.style.strokeDashoffset = this.getStrokeDashoffset().toString() + 'px';
        });
    }
    updatePercentage() {
        const increment = this.getNumberForValueString() > this.value ? 1 : -1;
        let currentPercentage = this.value;
        this.updateVisualization();
        // This is the animation loop that changes the numbers once per frame
        const update = () => {
            if (currentPercentage === this.getNumberForValueString()) {
                return;
            }
            currentPercentage += increment;
            this.value = currentPercentage;
            updateDynamicText(this);
            if (currentPercentage !== this.getNumberForValueString()) {
                this.requestAnimationFrameId = requestAnimationFrame(update);
            }
        };
        this.requestAnimationFrameId = requestAnimationFrame(update);
    }
    renderVisualization() {
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('class', 'neon-progress-circle-visualization');
        const circleBackground = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        circleBackground.setAttribute('class', 'neon-progress-circle-background');
        this.dataVisualizationBackground = circleBackground;
        const circleForeground = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        circleForeground.setAttribute('class', 'neon-progress-circle-foreground');
        // on init we want both the dasharray and dashoffset to be the full circumference, making it look like there is no fill
        // this works because the dashoffset is the amount of the dasharray that is not filled
        circleForeground.style.strokeDasharray = this.getStrokeDasharray().toString() + 'px';
        circleForeground.style.strokeDashoffset = this.getStrokeDasharray().toString() + 'px';
        this.dataVisualizationForeground = circleForeground;
        svg.appendChild(circleBackground);
        svg.appendChild(circleForeground);
        this.dataVisualization = svg;
        return createElement('div', {
            attrs: {
                class: 'neon-progress-circle-visualization-container'
            }
        }, svg, this.renderConditionalStatusIcon());
    }
    renderConditionalStatusIcon() {
        return createElementIf(() => { return this.getStateIcon() != null; }, 'neon-2_20_1-icon', {
            attrs: {
                'class': 'neon-progress-circle-status-icon',
                'data-icon': dynamicAttr(() => { return this.getStateIcon(); }),
                'data-size': dynamicAttr(() => { return this.getStateIconSize(); })
            }
        });
    }
    render() {
        return createElement('div', {
            attrs: { class: dynamicAttr(() => { return this.getClasses(); }) },
        }, this.renderVisualization(), createElement('div', {
            attrs: {
                class: 'neon-progress-circle-value'
            },
            text: dynamicText(() => { return this.value + '%'; })
        }), createElementIf(() => { return this.getAttribute('data-text') != null; }, 'div', {
            attrs: {
                class: 'neon-progress-circle-text'
            },
            text: dynamicText(() => { return this.getAttribute('data-text'); })
        }));
    }
}
